// Everstead's written scenes. Each character has one block: an introduction (shown when they join) and
// a few roaming encounters. A line is either narration (a string) or [speakerId, text]. A character
// without a block still gets a short generated introduction, so adding someone never breaks the game.
import {FELLOWS,FAMILY,characterById} from './cast.mjs';
import {SCENES_WAVE2} from './stories-wave2.mjs';
import {SCENES_WAVE2D} from './stories-wave2d.mjs';
import {SCENES_WAVE3} from './stories-wave3.mjs';
import {SCENES_WAVE4A} from './stories-wave4a.mjs';
import {SCENES_WAVE4B} from './stories-wave4b.mjs';
import {SCENES_WAVE4C} from './stories-wave4c.mjs';
import {SCENES_WAVE4D} from './stories-wave4d.mjs';
import {SCENES_WAVE4E} from './stories-wave4e.mjs';
import {SCENES_WAVE4F} from './stories-wave4f.mjs';
import {SCENES_WAVE4G} from './stories-wave4g.mjs';
import {SCENES_WAVE4H} from './stories-wave4h.mjs';
import {SCENES_WAVE4I} from './stories-wave4i.mjs';

/** @type {Record<string,{intro:any[],roams:{title:string,lines:any[]}[]}>} */
export const SCENES={
 // ---- Fellows ----
 obiwan:{intro:['A man in sand-colored robes sits on the Chapel steps, shaking grit out of one sleeve. Tatooine, he explains. It never fully leaves you.',['obiwan','Ah. There you are. You’ve been keeping your quiet mornings, haven’t you? It shows. You fidget less.'],['obiwan','Obi-Wan Kenobi. I spent twenty years in a desert waiting on one boy. I learned patience mostly because I had no other option.']],
  roams:[{title:'Breathing lesson',lines:['Obi-Wan asks you to sit and breathe. That’s it. No drill, no list.',['obiwan','You’re already planning Thursday. I can practically hear it. Come back to this morning, please.'],'It’s harder than any workout. Ten minutes in, your shoulders drop for the first time all week.']},
   {title:'The high ground',lines:['You find Obi-Wan on the hill above the village at sunrise, robes snapping in the wind.',['obiwan','I do like a bit of elevation. Old habit. Several of my worst days went much better from up high.'],['obiwan','Your troubles look rather smaller from here, don’t they? Take the view home with you. Pray on it.']]}]},
 din:{intro:['The Hearth Inn door opens and a man in beskar steps in, helmet on. A small green face peeks out of the satchel on his hip and coos.',['din','I took a job. Bring him in, collect the fee. I didn’t. I’ve been his father ever since.'],['din','Din Djarin. Your kids watch what you do, not what you say. This one copies everything I do. Even the bad stuff.']],
  roams:[{title:'Bedtime',lines:['Din sits by the fire while the little one falls asleep against his chest plate, one tiny hand on the Mudhorn signet.',['din','I’ve been shot at by a whole garrison. This is harder. He wakes up if I breathe wrong.'],'He doesn’t move for an hour. When you get up to leave, he lifts one finger off the kid to wave.']},
   {title:'Lessons',lines:['Din crouches beside the little one, who is trying to lift a pebble with the Force. It wobbles. It drops. They try again.',['din','I don’t lecture him. I sit next to him while he tries. Every day. Go sit on the floor with yours tonight.']]}]},
 darrow:{intro:['Before dawn, someone is already in the Training Yard, moving through a fighting form so fast the blade hums.',['darrow','You came back. Most come once, wake up sore, and decide they were never built for it.'],['darrow','Darrow. I was a Red. Dug helium in the mines under Lykos. They kept us small on purpose. I didn’t stay small.'],'He tosses you a practice blade and drops into a stance. No speech. Just the work.'],
  roams:[{title:'Rain drills',lines:['It’s pouring. Darrow is training anyway, hair plastered flat, grinning like a madman.',['darrow','Down in the mine we didn’t get weather. I’ll take rain over a rock ceiling any day. Come on.'],'You last ten minutes. He nods once. From Darrow, that’s a medal.']},
   {title:'The long climb',lines:['Darrow walks you up the hill behind the village with a pack of stones on his back. Then he hands you one.',['darrow','Sixteen years underground. Every hill still feels like a gift. Sevro says that’s a weird thing to get emotional about.'],['darrow','Your legs still climb. Don’t waste that. Same time tomorrow?']]}]},
 tony:{intro:['Sparks fly from a Market stall that’s been turned into a workshop. A man in a grease-stained tank top flips up his welding mask and grins.',['tony','You actually finish stuff? Huh. I’ve got forty prototypes in a garage and maybe six that work. Don’t look at me like that.'],['tony','Tony Stark. Genius, billionaire, recovering starter of projects. Let’s build something that actually ships.']],
  roams:[{title:'Ship it',lines:['Tony is glaring at a gadget that’s ninety percent done, already sketching the next one on a napkin.',['tony','The last ten percent is where the boring lives. Wiring, testing, cleanup. Nobody makes a montage of that part.'],'He finishes it before dinner and looks genuinely shocked. You confiscate the napkin.']},
   {title:'Lights off',lines:['Tony is locking up the workshop at a sensible hour. For once. He seems a little proud of himself.',['tony','Pepper’s rule. The suit’s only as good as the guy inside, and the guy runs on sleep. Apparently. I’m testing the theory.']]}]},
 peter:{intro:['A kid is up a ladder at the Workshop fixing a neighbor’s shutter, a half-eaten sandwich clamped in his teeth.',['peter','Oh, hey! Sorry, one sec. Mmf. Okay. Hi! You’re the guy who keeps the house running, right? Mr. Stark mentioned you. Kind of.'],['peter','Peter Parker. Saving the city’s cool, but somebody still has to take the trash out on Thursday. Turns out that’s the job too.']],
  roams:[{title:'Chore list',lines:['Peter is crossing items off a very long list taped to the Workshop door. One of them just says “homework (ugh).”',['peter','May’s rule: boring stuff first, then you’ve earned the fun. She’s right. I hate that she’s always right.']]},
   {title:'Helping out',lines:['Before lunch Peter carries groceries for Mrs. Hollis, fixes a fence and returns a very angry cat.',['peter','Little stuff piles up, good or bad. I’d rather it be the good pile. Ow. Okay, the cat’s still mad.']]}]},
 kaladin:{intro:['In the Library courtyard a spearman runs the same kata over and over, slow and exact. A ribbon of light zips around his head, giggling.',['kaladin','You keep the promises you make to yourself. Most people don’t even notice when they break them.'],['kaladin','Kaladin. I ran bridges for a while, with men nobody thought would live. Syl says I brood. I’m working on it.']],
  roams:[{title:'Grey days',lines:['Kaladin sits on the Library steps, staring at nothing. It’s the kind of tired that sleep doesn’t touch.',['kaladin','Fog rolled in this morning. I still ran the drill. Didn’t want to. I said I would.'],'Syl tugs at his collar. He sighs, stands, picks up the spear and starts.']},
   {title:'Carrying others',lines:['You watch Kaladin teach a shaking recruit how to hold a spear, the way he once taught Bridge Four.',['kaladin','We were dead men walking. We got out by doing the same small things together, every day, until it held.'],['kaladin','Your family leans on your routines more than you think. The workouts, the early nights. They feel it.']]}]},
 // ---- Family ----
 ariane:{intro:['At dusk the Chapel windows glow, though no candles are lit. A woman in white and blue robes turns, a soft light fading from her palm.',['ariane','Oh. It’s you. I wondered who kept leaving the pew warm in the mornings.'],['ariane','Ariane Lumenhart. I walked out of the Wizards’ Tower to be useful somewhere small. The archmages think I’ve lost my mind.'],'She lights a lantern with a touch and hands it to you. Her fingers brush yours and linger.'],
  roams:[{title:'Lantern spell',lines:['Ariane teaches you a simple light spell. Your first try makes a sad little spark that dies in a second.',['ariane','That’s more than I managed my first week. Again. I’ll stand right here. Closer, if it helps.'],'By the tenth try the spark holds. She’s looking at you, not the light.']},
   {title:'The quiet hour',lines:['You find Ariane alone in the empty Chapel, eyes closed, perfectly still.',['ariane','The Tower taught me a hundred spells. Sitting still and praying was the only one that changed me. Sit with me?'],'You sit beside her. Her shoulder settles against yours. It’s the calmest you’ve felt all week.']}]},
 tyrande:{intro:['Moonlight falls across the Rose Café though it’s barely dusk. A tall night elf priestess stands in it, a glaive on her back, watching the couples at the candlelit tables.',['tyrande','I’ve watched you. You keep choosing your wife, on the dull nights too. Elune smiles on that kind of man. So do I.'],['tyrande','Tyrande Whisperwind. My husband has slept through whole centuries. I kept my vows anyway. I’m told I’m stubborn.']],
  roams:[{title:'Night watch',lines:['You find Tyrande on the village wall long after midnight, silver eyes on the dark.',['tyrande','A Sentinel walks her rounds whether or not anything comes. Some nights I look in on every house.'],['tyrande','Go home. Kiss her goodnight. Properly. I’ll keep watch until you’re through the door.']]},
   {title:'The long vow',lines:['Tyrande turns a plain silver ring on her finger, the moon catching it.',['tyrande','Young lovers think vows live in the grand moments. Mine have lived on ten thousand years of ordinary Tuesdays.'],['tyrande','Supper together. A kind word when she’s tired. Put the work down and look at her. Then do it again tomorrow.']]}]},
 vin:{intro:['Something lands lightly on the Hearth Inn roof. A small, sharp-eyed young woman drops down beside you, a pouch of coins clinking at her belt.',['vin','I grew up in alleys. Nobody checked if I’d eaten. My brother mostly checked if I’d stolen enough.'],['vin','Vin. You actually show up for your kids. You don’t know what that’s worth. I do.']],
  roams:[{title:'Watching',lines:['Vin perches on a fence post, watching the kids in the square attempt handstands.',['vin','They don’t need you perfect. They need you to look up when they yell “watch this.” Every time. Even the ninth.']]},
   {title:'Trust',lines:['Vin flips you a coin. Then another. Then a third.',['vin','That’s how Kelsier got me to trust him. One kept promise at a time. Kids count every coin, believe me.']]}]},
 kira:{intro:['In the Training Yard a red-haired woman with a double-bladed practice staff sits on a sparring dummy she has clearly just beaten.',['kira','Oh good, fresh meat. The dummy stopped trying around lunch.'],['kira','Kira Carsen. I train every day, I talk the whole time, and I never skip. Two of those are virtues. You pick.']],
  roams:[{title:'Sparring',lines:['Kira taps your shoulder with a wooden blade. Then again. And again.',['kira','You drop your guard when you’re tired. Everyone does. Trick is getting tired later. And stop looking at my mouth. Guard up.'],'By the end you’re still losing, just slower. She calls it progress and bumps your hip on the way out.']},
   {title:'Rest day',lines:['You find Kira stretched out on the grass, for once not hitting anything.',['kira','I used to think rest days were for quitters. Then I pulled everything a person can pull.'],['kira','Lie down. Five minutes. I won’t tell anyone you liked it.']]}]},
 fannie:{intro:['Someone sprints past the Training Yard, skids to a stop and shoves a pair of rainbow goggles up into her hair.',['fannie','You run this loop too? Nice! Everybody bails at the hill. You didn’t bail.'],['fannie','Fannie! Explorer, trail runner, professional fresh-air getter. Come on, the next hill’s got a view.']],
  roams:[{title:'Trail run',lines:['Fannie drags you down a deer path you never noticed, all the way to a hidden waterfall. She’s barely winded.',['fannie','See? Every run, the map gets bigger. So does my mood. Yours too, look at your face.']]},
   {title:'Warm-up',lines:['Fannie refuses to let you start until you’ve done ten minutes of leg swings.',['fannie','Skip it once, fine. Skip it all month and your knees file a formal complaint. With me.']]}]},
 shallan:{intro:['At a Market table buried in books, a red-haired woman is sketching you before you’ve even said hello.',['shallan','Hold still. No, that’s worse. Go back to the brooding face. Yes. Storms, that’s good.'],['shallan','Shallan Davar. Scholar, artist, occasional liar, mostly to myself. Pattern says I talk too much. Pattern hums a lot.'],'She tears out the page and hands it over. You look far better in it than you did this morning.'],
  roams:[{title:'The sketchbook',lines:['Shallan flips through a sketchbook full of the village: the forge, the chapel, you hunched over your desk at dawn.',['shallan','I draw the work, not the finished thing. You look nice working. Focused. I’m not blushing, it’s the lamp.']]},
   {title:'The hard page',lines:['You find Shallan staring at a blank page, pencil frozen above it.',['shallan','The first honest line is always the worst one. I’d rather hide. I’d rather be anyone else, honestly.'],'She writes one. Then another. By sunset the page is full and she lets you read it.']}]},
 kate:{intro:['An arrow thunks into the Workshop door frame, pinning a loose shingle neatly back in place. A one-eyed golden retriever barks approvingly.',['kate','Sorry! Faster than finding a ladder. Mostly faster. Lucky, sit.'],['kate','Kate Bishop. I heard somebody around here actually keeps his house together. Respect. That’s harder than archery.'],'Lucky is already asleep on your boots. Kate decides that means she gets to stay.'],
  roams:[{title:'The ten-minute rule',lines:['Kate is speed-cleaning her kitchen with a timer running and terrible music on.',['kate','Ten minutes a night. Dishes, counters, done. Future Kate always sends a thank-you card.'],'The timer dings. The kitchen sparkles. Lucky licks the last crumb off the floor, which she counts as mopping.']},
   {title:'Target practice',lines:['Kate has chalked circles behind the Workshop around a broken hinge, a leaky gutter and a squeaky gate.',['kate','Every chore’s a target. Line up, let fly, next one. Bet I fix two before you fix one.'],'You fix three together before sundown. She claims she won. She didn’t.']}]},
 violet:{intro:['Steel flashes in the Library courtyard. A dagger thuds into the target, dead center, then another.',['violet','You’ve been keeping your word to yourself. Most people don’t. I noticed. I notice a lot.'],['violet','Violet Sorrengail. I was supposed to be a scribe. Basgiath had other plans. I trained until it stopped mattering what I was built for.'],'She pulls the daggers free and offers you one, handle first, holding your gaze a second too long.'],
  roams:[{title:'Dawn drills',lines:['Before sunrise, Violet is already in the courtyard running the same dagger drill, slow, then faster.',['violet','I’m never the strongest one in the ring. So I’m the one who’s practiced the most. Again.'],'She makes you do it twenty times. Then twenty more. Then she fixes your grip, her hand over yours.']},
   {title:'Bad days',lines:['Violet is moving carefully today, wrapping a swollen wrist with practiced hands.',['violet','Some days my joints just say no. I show up and do the small version anyway.'],['violet','The small version counts. If anyone tells you it doesn’t, send them to me. I have knives.']]}]},
 misty:{intro:['A splash at the lake, then a laugh. A red-haired girl in suspenders wades out holding a fishing rod over her head.',['misty','You took a whole day off just for fun? Finally! Everybody in this village works way too much.'],['misty','Misty, Cerulean Gym. Water trainer, swimmer, and the best angler you’ll ever meet. Grab a rod, and don’t scare the fish.']],
  roams:[{title:'Lake day',lines:['Misty challenges you to a fishing contest. She wins. By a lot. She is unbearable about it.',['misty','Okay, it’s not really about the fish. It’s that you’re out here and your phone’s in the bag. Also, I won.']]},
   {title:'Cannonball',lines:['Misty dares you to jump off the dock. You do. The water is freezing.',['misty','Ha! Your face! See, now you’re awake. Way better than another night on the couch, right?']]}]},
 roy:{intro:['A boy in a backwards cap sprints into the Training Yard, skids and nearly takes out a sandbag.',['roy','Whoa, sorry! Are you the one who trains every single day? Can I come? I wanna get stronger too!'],['roy','I’m Roy! Someday I’m gonna be the strongest. Today I’m just gonna be a little stronger than yesterday. That’s the plan!']],
  roams:[{title:'Race you',lines:['Roy challenges you to a race to the old oak. He wins, then demands a rematch, which you win.',['roy','You got faster in like five minutes! Imagine a whole year! Again! Again!']]},
   {title:'Big dreams',lines:['Roy lies in the grass, pointing at a cloud he insists looks like a dragon.',['roy','I bet every legend started out doing really bad push-ups. I’m on, like, twelve. Bad ones.']]}]},
 ash:{intro:['A young man in a red cap tips it at you from the Guildhall steps, a red-and-white ball spinning on one finger. A yellow mouse rides his shoulder.',['ash','You actually make time for the stuff you love? Awesome! Most grown-ups forget how. Right, Pikachu?'],['ash','Ash Ketchum, Pallet Town! I’ve been chasing the same dream since I was ten. Still having the best time ever.']],
  roams:[{title:'Practice match',lines:['Ash sets up a friendly match in the meadow and ends up cheering for both sides.',['ash','I lose all the time! Brock used to keep count. If you had fun and learned something, it totally counts.']]},
   {title:'Campfire stories',lines:['Ash tells stories by the fire until half the village is listening and nobody wants to go to bed.',['ash','Best part of any adventure is who’s sitting around the fire after. Bring someone next time!']]}]},
 ahsoka:{intro:['A hooded figure waits beneath the Chapel’s old tree, two white lightsabers hanging quiet at her hips.',['ahsoka','You’ve been quieter lately. Listening more. It suits you.'],['ahsoka','Ahsoka Tano. I’m no Jedi. I walked out of the Order years ago. The Force didn’t walk out on me.']],
  roams:[{title:'Meditation',lines:['Ahsoka sits with you on the hill, legs crossed, eyes closed. Her knee rests against yours.',['ahsoka','Don’t fight your thoughts. Just stop feeding them. My old master never managed it. You might.'],'After a while, the wind is the only thing you hear. When you open your eyes, she’s watching you.']},
   {title:'Her own path',lines:[['ahsoka','I left the Order. I didn’t leave what I believe. People mix those up.'],['ahsoka','Faith isn’t a temple. It’s what you do when nobody’s keeping score. Like praying before the kids wake up.']]}]},
 lys:{intro:['The smell of jasmine tea drifts from the Chapel garden, where a smiling woman in golden robes is setting out two cups.',['lys','Oh good, you came. I always pour an extra cup. Today I was hoping it would be yours.'],['lys','I’m Lys. I keep the old temple. Mostly that means sweeping, praying and making far too much tea.']],
  roams:[{title:'Morning prayers',lines:['Lys sweeps the temple steps, murmuring a prayer. She loses her place when she sees you, and laughs.',['lys','Now I have to start over. You’re very distracting. Sit and pray with me, then, so it counts double.']]},
   {title:'Gratitude jar',lines:['Lys shows you a jar stuffed with tiny folded notes.',['lys','One thank-you a night, for years. On bad days I read a few. Lately a lot of them are about you.']]}]},
 keyleth:{intro:['Vines curl up the Chapel wall and bloom as a red-haired druid with antlers steps out of them, then trips over a root.',['keyleth','Oh! Hi! Sorry. That was supposed to look way cooler. Ugh. Hi.'],['keyleth','I’m Keyleth. Air Ashari. I talk to trees and I worry. Like, a lot. The trees are very patient about it.']],
  roams:[{title:'Listening to the forest',lines:['Keyleth presses your hand flat against an old oak, her hand over yours.',['keyleth','Three hundred years, one ring at a time. It never once rushed. Is it weird that I find that romantic? It’s weird.']]},
   {title:'Self-doubt',lines:[['keyleth','Some days I’m sure I’m failing at everything. Leading, praying, being a person.'],['keyleth','Then Vex reminds me a seed doesn’t know it’s a tree yet. It just keeps going. Thanks for sitting with me.']]}]},
 padme:{intro:['At the Rose Café a woman in a white gown is writing a letter by candlelight, smiling to herself.',['padme','It’s for my husband. I write him something small every week, even when we’re in the same house. Especially then.'],['padme','Padmé Amidala. I’ve argued with entire planets in the Senate. None of it mattered like the person across my dinner table.']],
  roams:[{title:'Love letters',lines:['Padmé helps you write a note to leave on your wife’s pillow, leaning close to read over your shoulder.',['padme','It doesn’t need to be poetry. It needs to be true. Cross that out. Yes. She’ll keep this one.']]},
   {title:'Listening',lines:[['padme','The best negotiators I knew weren’t the loudest. They listened until the other side felt heard.'],['padme','Try it tonight. Phone in another room. Ask about her day, then ask a second question.']]}]},
 yennefer:{intro:['The Rose Café candles flare violet for a moment. A dark-haired sorceress who smells of lilac and gooseberries raises an eyebrow at you over her wine.',['yennefer','So you’re the man who still dates his own wife. Good. Most men stop trying the minute the vows are said.'],['yennefer','Yennefer of Vengerberg. I don’t do anything halfway. Sit up straight. You’re in better company than usual.']],
  roams:[{title:'No excuses',lines:[['yennefer','Too busy. Too tired. Next week. I’ve heard every excuse there is, in four languages, from kings.'],['yennefer','Book the sitter. Put the date on the calendar. Show up in a clean shirt. It isn’t magic, though it works like it.']]},
   {title:'Choosing',lines:['Yennefer watches a couple laughing by the fountain, and for once her mouth softens.',['yennefer','I was bound to a man by a wish once. I chose him anyway. The choosing is the only part that counts.']]}]},
 briget:{intro:['Rose petals drift across the Rose Café floor. A blonde princess in a sweeping blue gown curtsies to you with a mischievous smile.',['briget','I heard you remembered your anniversary without a single reminder. I nearly fainted. Truly. Someone fetch a chair.'],['briget','I’m Briget. I think every marriage deserves a little ceremony every week. Candles, a dance, a note under the coffee cup.']],
  roams:[{title:'Kitchen waltz',lines:['Briget teaches you a simple box step, counting softly in your ear, then makes you promise to try it in your kitchen tonight.',['briget','Nobody has ever regretted dancing with his wife. Not once in history. I checked the archives.']]},
   {title:'Little gifts',lines:['Briget shows you a basket of small surprises: a single flower, a favorite chocolate, a folded note.',['briget','It’s never the gift, silly. It’s her finding out you thought about her on a random Wednesday.']]}]},
 hera:{intro:['A green-skinned Twi’lek pilot with goggles pushed up on her forehead leans in the Hearth Inn doorway, watching the kids.',['hera','You get down on the floor with them. Eye level. Not many dads bother. I see it.'],['hera','Hera Syndulla, captain of the Ghost. I’ve flown through Imperial blockades. Raising Jacen with that crew was scarier.']],
  roams:[{title:'Patience',lines:['A kid spills an entire bowl of soup. Hera just laughs and tosses you a towel.',['hera','Soup wipes up. What they remember is your face when it happened. So smile, love.']]},
   {title:'Crew dinners',lines:[['hera','On the Ghost we ate together. Didn’t matter if Zeb and Ezra had just tried to kill each other.'],['hera','Get everyone at the table tonight. Screens off. That’s when a family remembers it’s a family.']]}]},
 liko:{intro:['A shy girl with blue hair peeks around the Hearth Inn doorway, hugging her bag to her chest.',['liko','Um, hi. Everyone says you’re a really good dad. Sorry. That’s a weird way to say hello.'],['liko','I’m Liko. I just left home for the first time. Everything feels really, really big right now.']],
  roams:[{title:'Big world',lines:['Liko shows you a small pencil drawing of a mountain she wants to climb someday.',['liko','It helps when somebody says “you can do it.” Even if it takes forever. Will you say it to your kids today?']]},
   {title:'Brave',lines:[['liko','I was so scared to leave home. But somebody back home checked on me every single night.'],['liko','That made me brave. Do that for your kids, okay? Even on the boring nights.']]}]},
 rey:{intro:['Someone has climbed to the top of the Training Yard’s highest post and is sitting up there, eating a ration bar.',['rey','Hello! View’s better up here. You stop noticing the climb after the first few thousand.'],['rey','I’m Rey. I grew up hauling scrap across Jakku for a quarter portion a day. No shortcuts. Just days.']],
  roams:[{title:'Salvage run',lines:['Rey drags you on a long hike to an old ruin and carries more than you can lift without a word of complaint.',['rey','On Jakku, if you didn’t haul it, you didn’t eat. Here you just get stronger. Same pack tomorrow?']]},
   {title:'Staff training',lines:['Rey runs a staff drill with you until your arms burn, then grins and taps your ribs with the end of it.',['rey','Again. Your body learns whatever you repeat. And you’re worth the extra round.']]}]},
 nemona:{intro:['A girl with a green streak in her hair is bouncing on her toes outside the Training Yard.',['nemona','You train every day? Yes! Finally, somebody to spar with! Let’s go, let’s go, let’s go!'],['nemona','Nemona! Champion rank! I love battling, running, training, all of it! It’s way more fun with a rival. You’re my rival now. No take-backs.']],
  roams:[{title:'Rival match',lines:['Nemona challenges you to most push-ups in a minute. She wins and immediately asks for a rematch.',['nemona','You did three more than yesterday! I counted! That’s so good! Again!']]},
   {title:'Fun first',lines:[['nemona','Training isn’t a chore! It’s a battle where you actually level up! Okay, rematch. Now. Please?']]}]},
 jaina:{intro:['A blonde archmage with a white streak in her hair studies a map of the whole valley in the Market hall, frost curling off her fingertips.',['jaina','You keep your work in order. That’s rarer than talent, believe me. I studied at Dalaran.'],['jaina','Jaina Proudmoore. I’ve run a fleet and a city. It was never brilliance that saved me. It was preparation.']],
  roams:[{title:'The long view',lines:['Jaina maps out your goals for the season in a tight, tidy hand. Your knees touch under the table. She doesn’t move hers.',['jaina','Today. This quarter. Ten years out. Now circle the one thing you’ll do before lunch tomorrow.']]},
   {title:'Lessons',lines:[['jaina','I’ve made decisions out of anger. I still pay for some of them.'],['jaina','Now I sleep on the hard calls and ask for counsel. Good work is rarely rushed.']]}]},
 nash:{intro:['A red-haired woman in a battered jacket drops a bag of coins on the Market counter and grins at you.',['nash','Job done, on time, as promised. That’s the whole trick, honestly. Nobody believes me.'],['nash','Nash Durango. I get paid because people know I deliver. And because I’m charming. Mostly the first one.']],
  roams:[{title:'On time',lines:[['nash','Show up early. Finish what you start. Answer your messages before lunch.'],['nash','You’d be amazed how far that gets you. Also, nice shirt. Just saying.']]},
   {title:'Payday',lines:['Nash splits her earnings into three pouches: save, spend, give. She tosses you the spend pouch to hold.',['nash','Lean months always come. A smart hunter’s ready for them. Now buy me a drink.']]}]},
 gwen:{intro:['Drumming echoes from the Workshop. A blonde girl in a white, pink-lined hood spins a drumstick and waves it at you.',['gwen','Hey! You’re the guy who keeps his place in order? Respect. I fight bad guys and I still have laundry.'],['gwen','Gwen Stacy. Drummer, Spider-Woman, terrible at folding fitted sheets. Turns out the small stuff is most of the stuff.']],
  roams:[{title:'Laundry day',lines:['Gwen turns folding laundry into a drum game, slapping a beat on the basket between shirts.',['gwen','If it’s got a beat, it’s not a chore. That’s my one rule. Okay, I have like four rules.']]},
   {title:'Reset',lines:[['gwen','Ten-minute reset every night. Dishes, counters, shoes by the door. My dad taught me that one.'],['gwen','Morning me thinks night me is a total legend.']]}]},
 alleria:{intro:['An arrow splits another arrow dead center on the Library’s practice target. A hooded elven ranger lowers her bow.',['alleria','Your focus is improving. Fewer glances at that little glowing slate of yours. I’ve been watching.'],['alleria','Alleria Windrunner. I’ve been shooting since before your kingdom had a name, and I still practice every morning. Partly vanity.']],
  roams:[{title:'One more arrow',lines:['Alleria has you shoot until your arms shake, then steadies your elbow with two fingers and murmurs: one more.',['alleria','Discipline lives in the last arrow. The one you wanted to skip. Draw. Breathe. There.']]},
   {title:'Stillness',lines:[['alleria','A ranger can lie in the brush for hours and not move a hair.'],['alleria','You can’t wait in a queue without your phone. We’ll fix that. Sit with me.']]}]},
 vex:{intro:['A ranger with a feathered braid is haggling a merchant down to half price outside the Library. A bear naps at her feet.',['vex','Darling, never pay full price for anything. Including distractions. They always cost more than they say.'],['vex','Vex’ahlia. That’s Trinket. I keep my arrows sharp, my purse heavy and my promises kept. Usually.']],
  roams:[{title:'Budget',lines:['Vex shows you her ledger. It is immaculate. She’s very proud of it.',['vex','Every coin has a job. So does every hour. Give them one before somebody else does. Ask me how I know.']]},
   {title:'Focus',lines:['Vex draws, holds and waits, perfectly still, for the right moment to loose. Then she winks at you instead.',['vex','Patience isn’t doing nothing. It’s refusing to do the wrong thing. Now you try, and stop staring at me.']]}]},
 rumi:{intro:['A melody drifts from the Guildhall stage. A woman with a long purple braid is drilling the same dance step for the twentieth time.',['rumi','Oh! You caught me. I rehearse every day, even the packed ones. Especially those.'],['rumi','I’m Rumi. Singing keeps me me. The demons get quieter when I do. Find your thing and guard it.']],
  roams:[{title:'Rehearsal',lines:['Rumi teaches you the first eight counts of a routine, laughing every time you turn the wrong way.',['rumi','Nobody’s good on day one. Day one is just for being brave. Five, six, seven, eight!']]},
   {title:'Sing it out',lines:[['rumi','When I’m stressed, I sing. Loud. Mira says I scare the pigeons.'],['rumi','Your hobby isn’t wasted time. It’s how you refill. Pick up that book tonight.']]}]},
 jester:{intro:['Someone has painted a giant smiley face on the Guildhall door. A blue tiefling with a lollipop-topped staff giggles behind it.',['jester','You found my art! Do you like it? I think it really ties the building together.'],['jester','I’m Jester Lavorre! I paint, I bake, I prank, and the Traveler says fun is holy. So really I’m just being very religious.']],
  roams:[{title:'Sketch session',lines:['Jester hands you her sketchbook and insists you draw a duck. It’s a terrible duck. She adores it.',['jester','Oh my gosh, he’s so ugly! I love him! See, it doesn’t have to be good to be good for you.']]},
   {title:'Pastries',lines:['Jester drags you into a kitchen to bake. Most of it turns into frosting experiments. One becomes a frosting mustache on you.',['jester','Making stuff with your hands is the best magic. Hold still, you have frosting... there. Okay, now more there.']]}]},
 tavi:{intro:['A young man in a red cloak is arguing cheerfully with a fierce, green-eyed woman outside the Rose Café. He loses, grins and holds the door for her.',['tavi','She wins most of our arguments. The trick is making sure we’re on the same side by the end.'],['tavi','Tavi. I grew up with no furycraft at all, so I had to be clever instead. Kitai still says “Aleran” like it’s an insult.']],
  roams:[{title:'Same side',lines:[['tavi','When we fight, I try to ask one thing. Is this us against each other, or us against the problem?'],['tavi','It changes everything. Try it next time the dishes turn into a war.']]},
   {title:'Small courtesies',lines:['Tavi carries a breakfast tray to his wife before dawn, every day, without being asked.',['tavi','First Lords forget the small things. Husbands can’t afford to. Kitai keeps a tally. A real one.']]}]},
 grog:{intro:['The ground shakes. A huge grey goliath strolls into the Training Yard carrying a boulder under one arm like a loaf of bread.',['grog','You lift stuff too? GREAT. Lifting stuff is the best.'],['grog','I’m Grog Strongjaw. I don’t know a lot of big words. But you pick up heavy stuff every day, you get strong. That’s it. That’s the whole secret.']],
  roams:[{title:'Leg day',lines:['Grog makes you carry a log twice around the village, walking beside you with a much bigger log.',['grog','Again tomorrow! And the next day! And the day after that one! I lost count. Keep going!']]},
   {title:'Friends',lines:['Grog shares an enormous lunch with you and makes you eat the vegetables first.',['grog','Pike says green stuff makes muscles. I don’t get it. But Pike’s never wrong, so. Eat the tree.']]}]},
 kelsier:{intro:['A man with a crooked grin and scarred forearms is laying out a heist on the Market table, using apples for guards.',['kelsier','You plan your days. Wonderful. Most people let the day plan them and then act surprised.'],['kelsier','Kelsier. Survivor of Hathsin, among other titles I gave myself. Know the goal, trust the crew, smile like you’ve already won.']],
  roams:[{title:'The plan',lines:['Kelsier helps you break your big work project into small, stealable pieces, walking a coin across his knuckles.',['kelsier','Nobody robs a vault in one move, my friend. One lock. Then the next. Tomorrow you pick the first lock.']]},
   {title:'Smile anyway',lines:[['kelsier','I learned to laugh on the worst days. Not because anything was fine. Nothing was.'],['kelsier','The crew needed to believe it could be. So do the people who watch you walk in the door at night.']]}]},
 shadowheart:{intro:['A dark-haired cleric kneels in the Chapel by moonlight, one hand closed around a silver pendant.',['shadowheart','I spent years praying to the wrong goddess. Finding the right one took longer than I’d like to admit. Don’t ask.'],['shadowheart','Shadowheart. I’m not good at this yet. But I come every night, and I listen. So do you, I’ve noticed.']],
  roams:[{title:'Moonlight prayer',lines:['Shadowheart teaches you a short prayer to Selûne, said under the open sky. Her shoulder is warm against yours.',['shadowheart','Faith isn’t certainty. It’s keeping the candle lit when you’re not sure anyone’s watching. Someone is, by the way. Me.']]},
   {title:'Second chances',lines:[['shadowheart','I was someone else once. Someone colder.'],['shadowheart','Every morning you choose who you serve. Choose well. Then come find me.']]}]},
 kitai:{intro:['A pale-haired Marat woman perches on the Rose Café railing, eating an apple and watching her husband with open amusement.',['kitai','He thinks I do not notice how hard he tries. I notice. I make him earn the compliment. Aleran men get lazy otherwise.'],['kitai','I am Kitai. Among my people, a marriage is a hunt that never ends. You keep chasing the one you already caught.']],
  roams:[{title:'The chase',lines:['Kitai challenges her husband to a race. She cheats outrageously. He pretends not to see.',['kitai','Keep it fun. A marriage with no play goes quiet fast. Chase your wife around the kitchen tonight. I mean it.']]},
   {title:'Bonded',lines:[['kitai','The Marat bond for life. It is not a choice, the elders say.'],['kitai','They are wrong. It is a choice. Every day you decide to stay, and every day it is worth it.']]}]},
 wanda:{intro:['Red light flickers in the Hearth Inn window. A woman in crimson is reading a bedtime story to a pile of sleepy children.',['wanda','They asked for one more chapter. They always ask for one more chapter.'],['wanda','Wanda Maximoff. I once rewrote a whole town so I could tuck my boys in. Nothing I built was as real as a kid asking you to stay.']],
  roams:[{title:'One more chapter',lines:['Wanda hands you the storybook. Three small faces turn toward you, waiting.',['wanda','Do the voices. They’ll remember the voices long after they forget the story.']]},
   {title:'Presence',lines:[['wanda','No spell gives you back the evenings you missed. Believe me, I looked.'],['wanda','So don’t miss them. Phone down, work tomorrow. Be on the floor with them tonight.']]}]},
 jean:{intro:['A red-haired woman is helping a nervous kid float a pencil in the Hearth Inn back room.',['jean','There. You did that. All I did was believe you could.'],['jean','Jean Grey. I teach at Xavier’s, kids who think something’s wrong with them. Mostly I just tell them there isn’t.']],
  roams:[{title:'Seeing them',lines:['Jean asks you to name one thing each of your kids is great at. You don’t even have to think.',['jean','Good. Now tell them. Today. Kids grow toward whatever you notice in them.']]},
   {title:'Patience',lines:[['jean','I can read minds, and kids still surprise me every single day.'],['jean','Ask them real questions at dinner. Then actually listen. You’d be amazed what’s in there.']]}]},
 karlach:{intro:['A wave of heat rolls across the Training Yard. A huge red tiefling with an infernal engine roaring in her chest high-fives you before you can say hello.',['karlach','Soldier! You train every day? Brilliant! We’re gonna be best mates, I can tell!'],['karlach','Karlach! Did ten years fighting in Avernus, so honestly, push-ups are a holiday. Come on, let’s get sweaty!']],
  roams:[{title:'Workout party',lines:['Karlach turns your workout into a loud, laughing contest with half the village, then lifts you clean off the ground when you win a round.',['karlach','Who says training’s got to be miserable? Turn it up! Oi, put your back into it, gorgeous!']]},
   {title:'Cool down',lines:['Karlach sits in the stream to cool her engine, steam hissing off her shoulders.',['karlach','Even I’ve got to cool down, or I literally catch fire. Rest is part of the fight, love. Sit with me.']]}]},
 carol:{intro:['A blonde woman in a red and blue flight jacket lands in front of the Market, checks her watch and nods.',['carol','You keep your commitments. Good. I hate wasted time almost as much as I hate losing.'],['carol','Carol Danvers. Air Force, then a lot more air. Same rule for all of it: show up, do the job, do it better tomorrow.']],
  roams:[{title:'Flight check',lines:['Carol walks you through her preflight checklist, every single item, even the ones she could do asleep.',['carol','Pros don’t skip the boring steps. That’s why they get to be pros. Your Monday needs a checklist.']]},
   {title:'Higher, further',lines:[['carol','I fell a lot as a kid. Off bikes, out of go-karts, flat on my face.'],['carol','Every time, I got back up. That’s the whole story. You look pretty good doing it too, by the way.']]}]},
 gamora:{intro:['A green-skinned woman reads through the Market ledgers, sharpening a blade without looking at it.',['gamora','Your work is clean. I respect clean work.'],['gamora','Gamora. Thanos raised me to be perfect. Now I aim for reliable. It is more useful, and fewer people get stabbed.']],
  roams:[{title:'Precision',lines:['Gamora reviews your to-do list and crosses off half of it without asking.',['gamora','You do not need more tasks. You need the right ones, done well. Start with this one. I will watch.']]},
   {title:'Crew',lines:[['gamora','I work with idiots. A raccoon, a tree, a man who dances when he should be fighting.'],['gamora','I would die for every one of them. Thank your team tomorrow. Out loud.']]}]},
 ororo:{intro:['On the Workshop roof, among potted herbs, a white-haired woman waters a garden while a soft rain falls only on it.',['ororo','You keep your home with care. I see it in the small things. The porch light. The swept step.'],['ororo','Ororo Munroe. I grew up on the streets of Cairo with nothing to tend. Now I can call a storm, and I would rather grow basil.']],
  roams:[{title:'Rooftop garden',lines:['Ororo shows you how to repot a struggling plant, guiding your hands into the soil with hers.',['ororo','A home is a living thing, my friend. Water it a little every day and it will hold you.']]},
   {title:'Calm',lines:[['ororo','When the house is cluttered, my mind clouds over. Sometimes literally.'],['ororo','Clear one counter. Breathe. Then the next. Shall we start with yours?']]}]},
 annamarie:{intro:['Someone has set a rocking chair on the Workshop porch, with a jug of sweet tea and two glasses already poured.',['annamarie','Well, hey there, sugar. Sit a spell. You look like you’ve been keepin’ this place in fine shape.'],['annamarie','Folks call me Rogue. My mama called me Anna Marie. Clean porch, open door, warm supper. That’s a home.']],
  roams:[{title:'Porch evening',lines:['Anna Marie makes you sit on the porch and do absolutely nothing for twenty minutes. She keeps her gloves on and her knee against yours.',['annamarie','A house ain’t just for cleanin’, darlin’. It’s for sittin’ in, too. Now hush and watch the fireflies.']]},
   {title:'Supper',lines:['Anna Marie cooks a huge pot of gumbo and invites the whole street.',['annamarie','Best kitchens are the messy ones, full of folks. You’re on dishes after, handsome.']]}]},
 laezel:{intro:['A githyanki warrior drills sword forms in the Library courtyard with terrifying precision. She stops and looks you over like a mount she might not buy.',['laezel','You train daily. Acceptable. Your form is still an embarrassment.'],['laezel','I am Lae’zel of Creche K’liir. Discipline is not punishment, istik. It is respect for what you could become. Try to keep up.']],
  roams:[{title:'Drills',lines:['Lae’zel corrects your stance for the fortieth time, kicking your heel into place.',['laezel','Again. Practice is worthless. Perfect practice is not. Tsk’va. Better.']]},
   {title:'Softer',lines:['You catch Lae’zel feeding a stray cat behind the Library. She glares at you over her shoulder.',['laezel','It depends on me. Discipline means caring for what depends on you. Speak of this and I gut you.']]}]},
 natasha:{intro:['You don’t hear the red-haired woman until she’s already beside you in the Library courtyard.',['natasha','You’re consistent. Makes you hard to surprise. I like that. Mostly.'],['natasha','Natasha Romanoff. The Red Room built me to be a weapon. I picked something else. Routine is how I keep picking it.']],
  roams:[{title:'Morning routine',lines:['Natasha runs her morning in exactly twenty minutes: stretch, train, plan. She hands you a coffee when she’s done.',['natasha','Routine handles the small stuff so your head’s free for what matters. Like me.']]},
   {title:'Ledger',lines:[['natasha','I’ve got a lot of old debts on my books.'],['natasha','Every good day is a little ink on the other side. You’re writing yours. I’m watching.']]}]},
 mira:{intro:['In the Guildhall a pink-haired dancer is running a routine in front of a mirror, counting under her breath.',['mira','Five, six, seven, eight. Oh. Hey. Yes, I’m rehearsing again. No, I won’t stop. You can watch, though.'],['mira','Mira. I choreograph everything myself. Dancing’s how I shut my head up.']],
  roams:[{title:'Choreography',lines:['Mira teaches you eight counts. You’re terrible. She’s thrilled.',['mira','Bad and consistent beats talented and lazy. Zoey started out bad. Don’t tell her I said that.']]},
   {title:'Head space',lines:[['mira','When everything gets loud, I dance until it’s quiet.'],['mira','Find your thing. Then protect the time for it like it’s a show night.']]}]},
 zoey:{intro:['A blue-haired girl is scribbling in a notebook on the Guildhall steps, humming a beat.',['zoey','Oh! Hi! Sorry, writing a verse. I write something every day. Most of it’s cringe. That’s the point!'],['zoey','I’m Zoey! Lyrics, raps, poems, grocery lists that rhyme. Making stuff makes me so happy.']],
  roams:[{title:'Notebook',lines:['Zoey dares you to write four lines about your day. They’re awful. She cheers like you dropped an album.',['zoey','You made something today that didn’t exist this morning! That’s huge! Okay, line three needs work.']]},
   {title:'Jam session',lines:['Zoey, Rumi and Mira turn a quiet evening at the Guildhall into a full-blown concert. Zoey drags you up for the chorus.',['zoey','Everything’s better with friends. Even your singing. Barely!']]}]},
 matt:{intro:['A man in red-tinted glasses sits in the back pew of the Chapel, rosary in hand, head tilted as if he’s listening to the whole village at once.',['matt','You’re here more lately. I can hear it. Your step’s lighter. Your heartbeat too.'],['matt','Matt Murdock. I’m not good at faith. I just keep showing up to it. Father Lantom says that counts.']],
  roams:[{title:'Confession',lines:['Matt steps out of the confessional and drops into the pew beside you, wincing at a fresh bruise.',['matt','Same sins every week. Same priest sighing at me. And every week I get to start over. That’s the deal.']]},
   {title:'Getting up',lines:[['matt','People ask how I keep going after a beating. My dad was a boxer. He always got up.'],['matt','You get knocked down, you pray, you get up. Missed your morning prayer? Fine. Get up tomorrow and pray.']]}]},
 tchalla:{intro:['A tall man in black stands at the edge of the Chapel garden at dusk, eyes closed, as if listening to voices only he can hear.',['tchalla','Forgive me. I was speaking with my father. The ancestors remind me who I am when I forget.'],['tchalla','I am T’Challa, of Wakanda. A king needs something greater than himself to answer to. So does a father.']],
  roams:[{title:'The ancestral plane',lines:['T’Challa asks you to stand with him in silence for the people who came before you. Your grandparents come to mind first.',['tchalla','Gratitude for those behind you. Responsibility for those ahead. My sister calls this brooding. It is prayer.']]},
   {title:'Tradition',lines:[['tchalla','In Wakanda we keep the old rites even when no one is watching.'],['tchalla','Especially then. That is when they shape you. Your evening prayer is the same.']]}]},
 steve:{intro:['At the Rose Café a man in a brown leather jacket is fixing an old record player, a big-band record already waiting.',['steve','I owed a girl a dance once. Took me about seventy years to keep that promise.'],['steve','Steve Rogers. Don’t wait like I did. Take your wife dancing this week. Saturday’s good. Saturday’s always good.']],
  roams:[{title:'The dance',lines:['Steve puts on an old song and walks you through a simple two-step, counting like a drill sergeant.',['steve','You don’t have to be good at it. Peggy was a lot better than me. You just have to ask her.']]},
   {title:'Loyalty',lines:[['steve','Bucky used to say I didn’t know when to quit. He had a point.'],['steve','That’s loyalty, I think. Not one big gesture. Showing up for her on the dull days. All of them.']]}]},
 logan:{intro:['A gruff man in a leather jacket sits on the Hearth Inn steps with a beer, letting a small kid try on his dog tags.',['logan','Don’t make a thing of it, bub. The kid asked.'],['logan','Logan. Spent a long time not caring about anybody. Then a kid needed me. Ruined everything. Best thing that ever happened.']],
  roams:[{title:'Patience',lines:['A kid asks Logan the same question for the tenth time. He answers it. The tenth time.',['logan','They don’t need you perfect. They need you there. Even when you’re tired. Especially then.']]},
   {title:'Soft spot',lines:[['logan','I’ve healed from bullets, fire, a building falling on me.'],['logan','Missing your kid’s game? That one doesn’t heal, bub. Don’t miss ’em.']]}]},
 quill:{intro:['Music blasts from an old cassette player at the Hearth Inn. A man in a red leather jacket is dancing with a pack of delighted kids.',['quill','Okay, okay, one more song! You’re all terrible dancers. Terrible. I love it.'],['quill','Peter Quill. Star-Lord? Legendary outlaw? No? My real dad was a planet. Long story. Yondu raised me. He was the real dad.']],
  roams:[{title:'Awesome mix',lines:['Quill makes a mixtape with your kids, letting each of them pick a song. One picks a song about a duck.',['quill','Twenty years from now they won’t remember the dishes. They’ll remember dancing to the duck song. Trust me.']]},
   {title:'Who shows up',lines:[['quill','Being a dad isn’t about being cool. Which is great, because Gamora says I’m not.'],['quill','It’s about being the guy who stayed. Every time. Yondu stayed. Took me way too long to get that.']]}]},
 bruce:{intro:['A rumpled man in glasses is scribbling equations on the Market chalkboard, sipping chamomile tea.',['bruce','Oh, hi. Sorry, I get absorbed. You keep good work habits. I, uh, respect that a lot, actually.'],['bruce','Bruce Banner. I have a, um, temper situation. Routine helps. Same desk, same tea, same hours. It helps a lot.']],
  roams:[{title:'Lab notes',lines:['Bruce shows you a notebook of daily experiments, every one logged, even the ones that exploded.',['bruce','Write down what you did today. Future you will want to know. Future me always does.']]},
   {title:'Calm',lines:[['bruce','When the pressure builds, I step away. Walk. Breathe. Count.'],['bruce','Good work doesn’t come out of anger. Believe me, I’ve tried. It comes out of boring, steady days.']]}]},
 piotr:{intro:['A huge man of polished steel is repainting a fence outside the Workshop with a tiny brush, humming a Russian folk song.',['piotr','You keep a tidy home. Good. My mother said a clean house is a calm heart. She was right about most things.'],['piotr','I am Piotr. Some call me Colossus. I would rather paint and cook than fight. Please, come in. Shoes off.']],
  roams:[{title:'Borscht',lines:['Piotr cooks an enormous pot of borscht and refuses to let you leave without a jar of it.',['piotr','On our farm in Siberia, the kitchen was the only warm room. So that is where we lived. Make yours warm.']]},
   {title:'Repairs',lines:['Piotr fixes a sagging porch step with his bare hands, then apologizes to it.',['piotr','Small repairs, right away. Wait one month, it is a big repair. Wait one year, it is a new porch.']]}]},
 stephen:{intro:['Floating books reshelve themselves in the Library. A man in a red cloak looks up from one, eyebrow raised, his scarred hands trembling slightly.',['stephen','You study every day. Good. Most people want mastery without the boredom. Doesn’t work. I checked.'],['stephen','Stephen Strange. I was a brilliant surgeon and a terrible student. Kamar-Taj fixed one of those. Guess which.']],
  roams:[{title:'Practice',lines:['Stephen makes you repeat one simple hand gesture for an hour. He doesn’t look up from his book once.',['stephen','I couldn’t open a single portal for months. Wong found it hilarious. Again. Your wrist is lazy.']]},
   {title:'Ego',lines:[['stephen','The hardest thing I learned at Kamar-Taj wasn’t magic.'],['stephen','It was admitting I’m not the smartest person in every room. Still working on it. Don’t tell Wong.']]}]},
 anakin:{intro:['A young Jedi is hacking through lightsaber forms in the Library courtyard, too fast and too hard.',['anakin','I’m the best duelist in the Order. Mostly. Okay, I still lose to Obi-Wan. Sometimes. Often.'],['anakin','Anakin Skywalker. Everyone says patience matters more than power. I’m learning. Slowly. Very slowly.']],
  roams:[{title:'Slow down',lines:['Anakin tries to rush a form again, then stops dead, like he can hear Obi-Wan sighing from across the village.',['anakin','Fine. Again. Slower. He was right. If you tell him I said that, I’ll deny it.']]},
   {title:'Temper',lines:[['anakin','When I get angry, I make terrible choices. Really terrible ones.'],['anakin','So I’m practicing. Breathe first. Phone down, saber down, whatever it is. Control first. Then power.']]}]},
 harry:{intro:['A young wizard circles the Guildhall on a broomstick, whooping, then lands badly in a hay pile.',['harry','Brilliant! Sorry. Needed a quick fly. Clears my head better than anything.'],['harry','Harry Potter. Catching dark wizards is the job. Quidditch on Sundays keeps me sane. Ron still shouts at the referee.']],
  roams:[{title:'Quidditch',lines:['Harry throws a ball at you over and over. You miss twenty times. He cheers anyway.',['harry','It’s not about being good. It’s about having a laugh with your mates. Again. Eyes open this time.']]},
   {title:'Joy',lines:[['harry','I spent my childhood in a cupboard under the stairs.'],['harry','So I take fun seriously now. A book, a game, whatever it is. Make the time. Nobody hands it to you.']]}]},
 thor:{intro:['The Guildhall doors burst open. A god with a hammer strides in, roaring with laughter, and orders a feast for everyone.',['thor','You! I hear you make time for joy! Excellent! Most mortals forget how. More mead!'],['thor','I am Thor, son of Odin. A warrior must also feast, play and sing. It is the law. My law. I just made it.']],
  roams:[{title:'Game night',lines:['Thor challenges the whole village to a board game and loses spectacularly. He demands a rematch at once.',['thor','Losing is half the fun! The other half is winning! Again! Loki cheats at these, you know.']]},
   {title:'Adventure',lines:[['thor','Every week I try something new. A new food. A new place. A new song.'],['thor','Life is long, my friend. Far too long to be boring. What will you learn this week?']]}]},
 geralt:{intro:['A white-haired swordsman drops a drowner’s head by the Training Yard fence and starts stretching, like it’s any other Tuesday.',['geralt','Hm. You train every day.'],['geralt','Geralt. Witchers don’t get days off. Monsters don’t either. Grab a sword. Not that one.']],
  roams:[{title:'Sword drills',lines:['Geralt runs you through the same three sword forms until the sun is gone. He says maybe four words.',['geralt','Same forms. Every day. Your body remembers when your head’s too busy. That’s how you live.']]},
   {title:'Meditation',lines:['Geralt sits cross-legged by the fire, eyes closed. Roach grazes nearby. A potion bottle sits by his knee, unopened.',['geralt','Rest. Part of training. Skip it, you get sloppy. Sloppy gets you killed. Or sore.']]}]},
};

/** Introductions, keyed by character id. */
Object.assign(SCENES,SCENES_WAVE2,SCENES_WAVE2D,SCENES_WAVE3,SCENES_WAVE4A,SCENES_WAVE4B,SCENES_WAVE4C,SCENES_WAVE4D,SCENES_WAVE4E,SCENES_WAVE4F,SCENES_WAVE4G,SCENES_WAVE4H,SCENES_WAVE4I);
export const INTROS=Object.fromEntries(Object.entries(SCENES).map(([id,s])=>[id,s.intro]));
/** Roaming encounters. `with` must have joined for the scene to appear. Family scenes grant bond; Fellow scenes grant a little gold. */
export const ROAMS=Object.entries(SCENES).flatMap(([id,s])=>s.roams.map((r,i)=>({id:id+'-'+(i+1),with:id,...r})));

/** Village vignettes, available any time. */
export const VILLAGE=[
 {id:'village-1',title:'Market morning',lines:['The market’s loud this morning. A kid sells you a slightly squashed apple for one copper and counts it twice.','Best apple you’ve had all year. You tell her so. She raises the price.'],gold:40},
 {id:'village-2',title:'Lost hen',lines:['A hen has escaped and is leading half the village on a chase through the gardens. Grog is losing badly.','You catch it. The farmer pays you in eggs, coin and a very long story about the hen.'],gold:60},
 {id:'village-3',title:'Notice board',lines:['Someone has pinned a note to the village board: “Whoever keeps fixing stuff around here, thank you.”','You don’t mention it was you. Peter definitely knows.'],gold:30},
 {id:'village-4',title:'Old map',lines:['In the inn’s attic you find an old map of Everstead. Back then it was one cottage and a well.','Every building since went up one plank, one day at a time. Yours too.'],gold:50},
];

const FAMILY_BOND=40,FELLOW_GOLD=120;
function pick(list,seen,now){const fresh=list.filter(s=>!seen.includes(s.id)),pool=fresh.length?fresh:list;return pool[Math.abs(Math.floor(now/1000))%pool.length]}
/** Choose a roaming scene for this state: prefer unseen scenes with joined characters, mix in the village. */
export function roamScene(state,now){
 const joined=new Set([...Object.keys(state.fellows||{}),...Object.keys(state.family||{})]);
 const people=ROAMS.filter(s=>joined.has(s.with));
 const useVillage=!people.length||Math.floor(now/1000)%4===0;
 const seen=state.roam?.seen||[];
 if(useVillage){const v=pick(VILLAGE,seen,now);return {...v,kind:'village',with:null,bond:0,gold:v.gold,summary:v.title+' · +'+v.gold+' gold'}}
 const s=pick(people,seen,now),who=characterById(s.with),isFamily=FAMILY.some(f=>f.id===s.with);
 return {...s,kind:isFamily?'family':'fellow',bond:isFamily?FAMILY_BOND:0,gold:isFamily?0:FELLOW_GOLD,summary:`${s.title} with ${who.name} · `+(isFamily?`+${FAMILY_BOND} bond`:`+${FELLOW_GOLD} gold`)};
}
/** The introduction scene for a character; characters without a written one get a short generated intro. */
export function introFor(id){const who=characterById(id);if(!who)return null;const lines=INTROS[id]||[`${who.name} arrives in Everstead.`,[id,`I am ${who.fullName||who.name}. I have heard about you. Let us get to work.`],who.description];return {id:'intro:'+id,title:'Meet '+who.name,lines}}
export const ALL_SPEAKERS=[...FELLOWS,...FAMILY];
